SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, ROUND(AVG(salary), 2) AS avg_salary, MAX(salary) FILTER (WHERE level = 'L4') AS l4_max_salary, COUNT(*) FILTER (WHERE level = 'L2') AS l2_rows FROM employees GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', hire_date), CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('MONTH', hire_date)));
